import{_ as i,l,o as e,c as o,v as r,p as s,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"分支发散","description":"","frontmatter":{"title":"分支发散","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/warp-divergence.md","filePath":"cs/warp-divergence.md","lastUpdated":1789023840000}'),h={name:"cs/warp-divergence.md"};function _(m,a,u,f,g,E){const n=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="分支发散" tabindex="-1">分支发散 <a class="header-anchor" href="#分支发散" aria-label="Permalink to &quot;分支发散&quot;">​</a></h1><div class="epigraph"><p>warp 必须共享 PC：一半线程走 then、一半走 else 时，硬件串行执行两条路径，掩码关掉另一半 lane，再汇合。</p><footer>—— 据 Fung et al., Dynamic Warp Divergence Management；Lindholm et al., IEEE Micro 2008 整理</footer></div><p><a href="/cs/gpu-memory-hierarchy">上一课</a> 假定 lane 都在干活。<a href="/cs/gpu-simt">SIMT</a> 的共享 PC 在 <code>if</code> 上破裂。本课不重讲 HBM。缺口是<strong>发散：用执行掩码串行化 divergent 路径，以及它对有效吞吐的惩罚。</strong> 不是 CPU <a href="/cs/gshare-predictor">gshare</a> 的误预测冲刷。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CPU：不同线程独立 PC，分支只影响自己的窗口。SIMT：32 线程一票。若条件按线程 ID 棋盘分布，then 与 else 都要跑一遍，峰值 FLOP 减半（两路）或更差（嵌套）。缺口不是加预测器让一半线程去错误路径投机——GPU 通常不那么做——而是<strong>掩码 + 重汇合点。</strong></p><p><span class="marginnote">汇合：编译器插入汇合点，或硬件栈记下 diverged 的 PC 与掩码。Fung 等讨论动态重组 warp 以减少持久发散，属优化，本课先钉基本串行化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>遇到分支：根据每线程条件拆成掩码子集，逐个子集执行对应目标，非活动 lane 不写寄存器。嵌套用栈。汇合后恢复全 1 掩码。无发散则一条路径，满宽。</p>',8)),(e(),s(c,null,{default:t(()=>[p(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BR%5B%22warp%20%E5%86%85%E5%88%86%E6%94%AF%22%5D%20--%3E%20M1%5B%22%E6%8E%A9%E7%A0%81%20A%20%E8%B5%B0%20then%22%5D%0A%20%20BR%20--%3E%20M2%5B%22%E6%8E%A9%E7%A0%81%20B%20%E8%B5%B0%20else%22%5D%0A%20%20M1%20--%3E%20JOIN%5B%22%E6%B1%87%E5%90%88%22%5D%0A%20%20M2%20--%3E%20JOIN%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有效 SIMT 宽度 = 活跃 lane 比例，再对路径数求和（串行）。这是 Flynn SIMD 格的控制税。与 CPU 误预测不同：两条路径都是架构上要执行的（不同线程），不是猜错。算法上应让相邻线程走同一路（warp-aware 数据布局）。</p><p>嵌套与循环内分支会把栈加深，持久发散（一个 warp 长期只剩几条活跃）比一次性 if/else 更伤：寄存器仍按全 warp 分配，占用率并不因掩码变稀而回收。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把独立线程 MIMD 化当成默认修复——那失去 SIMT 密度。下一课合并访存：即使不发散，地址散乱仍会把一拍变成多次内存事务。</p><p>后课默认：控制发散按路径串行加掩码。地址发散（非合并）是带宽另一税。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>发散 = 共享 PC 下多路径串行 + 掩码。</li><li>惩罚是架构路径都要跑，不是预测冲刷。</li><li>全局访存如何合成事务，是下一课合并。</li><li>出处：Lindholm et al.；Fung et al. 对 warp 发散的管理。</li></ul>',8))])}const A=i(h,[["render",_]]);export{T as __pageData,A as default};
